     * @param {object} opts
     * @param {'ig'|'stratum'|'public'} opts.ownerType
     * @param {string} opts.owner — Soylent | Magrail | Brazos | first | second | third_wave | rich | …
     * @param {string} [opts.id] — stable id for seeding
     * @param {boolean} [opts.isHome]
     */
    function pickOwnerDisplayName(opts) {
        opts = opts || {}
        var owner = String(opts.owner || '')
        var seed = opts.id || (owner + '_' + (opts.district || '') + '_' + (opts.isHome ? 'home' : 'asset'))

        if (opts.ownerType === 'ig') {
            if (owner === 'Soylent') { return pickSoylent(seed) }
            if (owner === 'Magrail') { return pickMagrail(seed) }
            if (owner === 'Brazos') { return pickBrazos(seed) }
            return pick(owner.toLowerCase(), seed) || owner + ' Facility'
        }

        if (owner === 'first') { return pickFirstWave(seed) }
        if (owner === 'second') { return pickSecondWave(seed) }
        if (owner === 'third_wave') { return pickThirdWave(seed) }
        if (owner === 'rich') { return pickRich(seed) }
        if (owner === 'deeper') { return pickDeeper(seed) }
        if (owner === 'coop') { return pickCoop(seed) }

        return pickThirdWave(seed)
    }

    q.pickOwnerDisplayName = pickOwnerDisplayName
}
// END sync:economic-name-catalog


function ensureEconomicAssets() {
    if (!Q.economicAssets) { Q.economicAssets = [] }
}

function addEconomicRecord(rec) {
    ensureEconomicAssets()
    var entry = {
        level: 1,
        health: 1,
        major: false,
        infraWeight: 0.8,
        outputPerLevel: 0.08,
        countsAsHome: false,
    }
    for (var k in rec) {
        if (Object.prototype.hasOwnProperty.call(rec, k)) { entry[k] = rec[k] }
    }
    if (entry.countsAsHome) {
        entry.kind = entry.kind || 'megaplex'
        entry.outputPerLevel = 0
        if (!entry.infraWeight || entry.infraWeight === 0.8) { entry.infraWeight = 1.2 }
    } else if (!entry.kind) {
        entry.kind = 'office'
    }
    if (!entry.id) {
        entry.id = entry.owner + '_' + entry.district + '_' + Q.economicAssets.length
    }
    Q.economicAssets.push(entry)
    return entry
}

function addAsset(opts) {
    var rec = {}
    for (var k in opts) {
        if (Object.prototype.hasOwnProperty.call(opts, k)) { rec[k] = opts[k] }
    }
    rec.countsAsHome = false
    return addEconomicRecord(rec)
}

function addHome(opts) {
    var rec = {}
    for (var k in opts) {
        if (Object.prototype.hasOwnProperty.call(opts, k)) { rec[k] = opts[k] }
    }
    rec.countsAsHome = true
    return addEconomicRecord(rec)
}

/** Strata that own housing stock (not drones / corps). Pop in 10,000s; 1 home per 100k people. */
var ECONOMIC_HOME_STRATA = [
    'rich', 'first', 'second', 'coop', 'third_wave', 'alien', 'deeper',
]

/** Target homes = floor(required × 1.2) where required = ceil(pop / 10). */
function homesTargetForPopulation(popInTenThousands) {
    var pop = Number(popInTenThousands)
    if (isNaN(pop) || pop <= 0) { return 0 }
    var required = Math.ceil(pop / 10)
    return Math.floor(required * 1.2)
}

function hasEconomicAssetId(id) {
    if (!Q.economicAssets) { return false }
    for (var i = 0; i < Q.economicAssets.length; i++) {
        if (Q.economicAssets[i].id === id) { return true }
    }
    return false
}

/** Seed homes once at start — ~20% above quota (post–population-decline recovery). */
function initEconomicAssets() {
    if (Q.economicAssetsInitialized) { return }
    Q.economicAssetsInitialized = 1
    if (typeof installEconomicNameCatalog === 'function') {
        installEconomicNameCatalog(Q)
    }
    ensureEconomicAssets()

    if (!hasEconomicAssetId('pitts_skill_issue_heights')) {
        addHome({
            id: 'pitts_skill_issue_heights',
            name: 'Skill Issue Heights',
            district: 'Pitts',
            ownerType: 'stratum',
            owner: 'rich',
            major: true,
        })
    }

    var state = Q.electionV2
    if (!state || !state.blocks || typeof Q.pickOwnerDisplayName !== 'function') {
        return
    }

    var byStratumDistrict = {}
    for (var bi = 0; bi < state.blocks.length; bi++) {
        var block = state.blocks[bi]
        var sid = block.demographic.id
        if (ECONOMIC_HOME_STRATA.indexOf(sid) < 0) { continue }
        var did = block.district.id
        if (!byStratumDistrict[sid]) { byStratumDistrict[sid] = {} }
        byStratumDistrict[sid][did] = (byStratumDistrict[sid][did] || 0) + block.population
    }

    for (var si = 0; si < ECONOMIC_HOME_STRATA.length; si++) {
        var stratum = ECONOMIC_HOME_STRATA[si]
        var districtPops = byStratumDistrict[stratum]
        if (!districtPops) { continue }

        var totalPop = 0
        for (var dk in districtPops) {
            if (Object.prototype.hasOwnProperty.call(districtPops, dk)) {
                totalPop += districtPops[dk]
            }
        }
        if (totalPop <= 0) { continue }

        var target = homesTargetForPopulation(totalPop)
        if (target <= 0) { continue }

        var skillInPitts = (
            stratum === 'rich' && hasEconomicAssetId('pitts_skill_issue_heights')
        )
        var alreadyPlaced = skillInPitts ? 1 : 0
        var toPlace = target - alreadyPlaced
        if (toPlace <= 0) { continue }

        var districtRows = []
        for (var distId in districtPops) {
            if (!Object.prototype.hasOwnProperty.call(districtPops, distId)) { continue }
            var share = districtPops[distId] / totalPop
            var exact = toPlace * share
            districtRows.push({
                id: distId,
                base: Math.floor(exact),
                frac: exact - Math.floor(exact),
            })
        }

        var assigned = 0
        for (var dr = 0; dr < districtRows.length; dr++) {
            assigned += districtRows[dr].base
        }
        var remainder = toPlace - assigned
        districtRows.sort(function(a, b) { return b.frac - a.frac })
        for (var rr = 0; rr < remainder && rr < districtRows.length; rr++) {
            districtRows[rr].base += 1
        }

        for (var dj = 0; dj < districtRows.length; dj++) {
            var row = districtRows[dj]
            for (var hi = 0; hi < row.base; hi++) {
                if (skillInPitts && row.id === 'Pitts' && hi === 0) {
                    continue
                }
                var homeId = 'home_' + stratum + '_' + row.id + '_' + hi
                if (hasEconomicAssetId(homeId)) { continue }
                addHome({
                    id: homeId,
                    name: Q.pickOwnerDisplayName({
                        ownerType: 'stratum',
                        owner: stratum,
                        district: row.id,
                        id: homeId,
                        isHome: true,
                    }),
                    district: row.id,
                    ownerType: 'stratum',
                    owner: stratum,
                    major: false,
                })
            }
        }
    }
}

var ECONOMIC_STRATUM_LABELS = {
    rich: 'Rich',
    first: '1st Wave',
    second: '2nd Wave',
    coop: 'Coops',
    drone: 'Drones',
    alien: 'Otherworlders',
    deeper: 'Deepers',
    third_wave: '3rd Wave',
}

function sortedEconomicAssets() {
    ensureEconomicAssets()
    var assets = Q.economicAssets || []
    return assets.slice().sort(function(a, b) {
        if (a.district !== b.district) {
            return a.district < b.district ? -1 : 1
        }
        if (!!a.countsAsHome !== !!b.countsAsHome) {
            return a.countsAsHome ? -1 : 1
        }
        var an = a.name || a.id
        var bn = b.name || b.id
        return an < bn ? -1 : (an > bn ? 1 : 0)
    })
}

function economicAssetTypeLabel(entry) {
    var typeLabel = entry.countsAsHome ? 'Home' : 'Asset'
    if (entry.kind) { typeLabel += ' (' + entry.kind + ')' }
    return typeLabel
}

function economicAssetStatusLabel(entry) {
    return (entry.health == null || Number(entry.health) >= 1) ? 'Operational' : 'Offline'
}

function appendEconomicReportCell(tr, text, tagName) {
    var cell = document.createElement(tagName || 'td')
    cell.style.textAlign = 'left'
    cell.style.padding = '0.15em 0.35em 0.15em 0'
  if (tagName === 'th') {
        cell.style.fontWeight = 'normal'
    }
    cell.textContent = text
    tr.appendChild(cell)
    return cell
}

function appendEconomicAffiliationCell(tr, entry) {
    var td = document.createElement('td')
    td.style.textAlign = 'left'
    td.style.padding = '0.15em 0.35em 0.15em 0'

    if (entry.ownerType === 'ig') {
        var color = '#44b88f'
        var tag = 'Corp'
        if (
            entry.owner === 'Families'
            || entry.owner === 'Edges'
            || entry.owner === 'Sharks'
        ) {
            color = '#cf6e19'
            tag = 'Syndicate'
        }
        var span = document.createElement('span')
        span.style.color = color
        span.textContent = entry.owner
        td.appendChild(span)
        td.appendChild(document.createTextNode(' (' + tag + ')'))
    } else if (entry.ownerType === 'public') {
        var forLabel = entry.housingFor
            ? (ECONOMIC_STRATUM_LABELS[entry.housingFor] || entry.housingFor)
            : 'general'
        td.textContent = 'City (' + forLabel + ' housing)'
    } else {
        var stratumName = ECONOMIC_STRATUM_LABELS[entry.owner] || entry.owner
        td.textContent = stratumName + ' (stratum)'
    }

    tr.appendChild(td)
}

/** DOM report (see mod_loader.scene.dry): fill a placeholder div from on-display. */
function renderEconomicAssetsReport(containerId) {
    var root = document.getElementById(containerId || 'jacobs_assets_report')
    if (!root) { return }
    root.innerHTML = ''

    if (typeof ensureEconomicAssets !== 'function') {
        var missing = document.createElement('p')
        var em = document.createElement('em')
        em.textContent = 'Economic registry is not available yet.'
        missing.appendChild(em)
        root.appendChild(missing)
        return
    }

    var rows = sortedEconomicAssets()
    if (!rows.length) {
        var empty = document.createElement('p')
        var emptyEm = document.createElement('em')
        emptyEm.textContent = 'No registered homes or economic assets yet.'
        empty.appendChild(emptyEm)
        root.appendChild(empty)
        return
    }

    var table = document.createElement('table')
    table.style.width = '100%'
    table.style.borderCollapse = 'collapse'
    table.style.fontSize = '0.85em'
    table.style.margin = '0.25em 0'

    var header = document.createElement('tr')
    appendEconomicReportCell(header, 'Site', 'th')
    appendEconomicReportCell(header, 'Type', 'th')
    appendEconomicReportCell(header, 'District', 'th')
    appendEconomicReportCell(header, 'Affiliation', 'th')
    appendEconomicReportCell(header, 'Status', 'th')
    table.appendChild(header)

    for (var i = 0; i < rows.length; i++) {
        var e = rows[i]
        var tr = document.createElement('tr')
        appendEconomicReportCell(tr, e.name || e.id)
        appendEconomicReportCell(tr, economicAssetTypeLabel(e))
        appendEconomicReportCell(tr, e.district || '')
        appendEconomicAffiliationCell(tr, e)
        appendEconomicReportCell(tr, economicAssetStatusLabel(e))
        table.appendChild(tr)
    }

    root.appendChild(table)

    var foot = document.createElement('p')
    foot.style.fontSize = '0.85em'
    foot.style.margin = '0.35em 0 0 0'
    foot.textContent = rows.length + ' sites registered.'
    root.appendChild(foot)
}

function formatEconomicAssetsReportHtml() {
    var rows = sortedEconomicAssets()
    if (!rows.length) {
        return '<p><em>No registered homes or economic assets yet.</em></p>'
    }

    var html = '<table style="width:100%;border-collapse:collapse;font-size:0.85em;margin:0.25em 0;">'
    html += '<tr><th style="text-align:left;font-weight:normal;">Site</th>'
    html += '<th style="text-align:left;font-weight:normal;">Type</th>'
    html += '<th style="text-align:left;font-weight:normal;">District</th>'
    html += '<th style="text-align:left;font-weight:normal;">Affiliation</th>'
    html += '<th style="text-align:left;font-weight:normal;">Status</th></tr>'

    for (var i = 0; i < rows.length; i++) {
        var e = rows[i]
        html += '<tr><td style="text-align:left;">' + (e.name || e.id) + '</td>'
        html += '<td style="text-align:left;">' + economicAssetTypeLabel(e) + '</td>'
        html += '<td style="text-align:left;">' + (e.district || '') + '</td>'
        html += '<td style="text-align:left;">'
        if (e.ownerType === 'ig') {
            var color = '#44b88f'
            var tag = 'Corp'
            if (
                e.owner === 'Families' || e.owner === 'Edges' || e.owner === 'Sharks'
            ) {
                color = '#cf6e19'
                tag = 'Syndicate'
            }
            html += '<span style="color:' + color + ';">' + e.owner + '</span> (' + tag + ')'
        } else if (e.ownerType === 'public') {
            var forLabel = e.housingFor
                ? (ECONOMIC_STRATUM_LABELS[e.housingFor] || e.housingFor)
                : 'general'
            html += 'City (' + forLabel + ' housing)'
        } else {
            html += (ECONOMIC_STRATUM_LABELS[e.owner] || e.owner) + ' (stratum)'
        }
        html += '</td><td style="text-align:left;">' + economicAssetStatusLabel(e) + '</td></tr>'
    }

    html += '</table>'
    html += '<p style="font-size:0.85em;margin:0.35em 0 0 0;">'
    html += rows.length + ' sites registered.</p>'
    return html
}

function monthly_tick_phase1() {
    organize_tick()
    trade_level_tick()
    economy_tick()
    applyStratumProsperityBumps()
    applyProsperityConnections()
    syncProsperityDisplays()
}

Q.monthly_tick_phase1 = monthly_tick_phase1
Q.applyStratumProsperityBumps = applyStratumProsperityBumps
Q.applyProsperityConnections = applyProsperityConnections
Q.syncProsperityDisplays = syncProsperityDisplays
Q.ensureEconomicAssets = ensureEconomicAssets
Q.addAsset = addAsset
Q.addHome = addHome
Q.initEconomicAssets = initEconomicAssets
Q.formatEconomicAssetsReportHtml = formatEconomicAssetsReportHtml
Q.renderEconomicAssetsReport = renderEconomicAssetsReport

initEconomyProsperity()
initEconomicAssets()
syncProsperityDisplays()

!}

title: Setup organizing tick functions
max-visits: 1
new-page: false
on-arrival: {!

Q.trade_level = 1.123
Q.corp_money = 5000
Q.corp_capital = 50000
Q.drone_money = 2000
Q.affluent_money = 500
Q.poor_money = 1000
Q.coop_money = 1500
Q.coop_capital = 10000

const PROSPERITY_BASELINE = 1.0
const PROSPERITY_CLAMP_MIN = 0.5
const PROSPERITY_CLAMP_MAX = 1.5
/**
 * Monthly prosperity bleed between voter blocks (and corps/syndicates on Q).
 * Mirrors ElectorateModifier: catalog rows, optional stackId on Q for card-driven links.
 *
 * Positional:
 *   new ProsperityConnectionModifier(rowId, fromScope, fromTarget, toScope, toTarget, coefficient [, opts])
 * Object: { id, fromScope, fromTarget, toScope, toTarget, coefficient, basis?, self_feedback?, stackId?, activeIf? }
 *
 * basis: 'level' (default) | 'excess' (prosperity − 1.0)
 * self_feedback: true → each destination uses its own prosperity as the source (stratum self-decay)
 * quality scope: fromTarget is a Q quality (e.g. trade_level); signal uses (value − 1) when basis is excess
 */
class ProsperityConnectionModifier {
    constructor(rowId, fromScope, fromTarget, toScope, toTarget, coefficient, opts) {
        if (rowId && typeof rowId === 'object') {
            opts = rowId
            rowId = opts.id
            fromScope = opts.fromScope
            fromTarget = opts.fromTarget
            toScope = opts.toScope
            toTarget = opts.toTarget
            coefficient = opts.coefficient
        } else if (typeof opts !== 'object' || opts === null) {
            opts = {}
        }
        this.id = rowId
        this.fromScope = fromScope
        this.fromTarget = fromTarget || ''
        this.toScope = toScope
        this.toTarget = toTarget || ''
        this.coefficient = coefficient || 0
        this.basis = opts.basis || 'level'
        this.self_feedback = !!(opts.self_feedback || opts.local)
        this.stackId = opts.stackId || null
        this.activeIf = opts.activeIf || function() { return true }
    }

    stacksFromQ(q) {
        if (!this.stackId) { return 1 }
        if (!q || q[this.stackId] == null) { return 0 }
        var n = Number(q[this.stackId])
        if (isNaN(n) || n <= 0) { return 0 }
        return n
    }

    isActive(q) {
        try {
            return !!this.activeIf(q)
        } catch (e) {
            return false
        }
    }

    basisAmount(value) {
        var v = Number(value)
        if (isNaN(v)) { v = PROSPERITY_BASELINE }
        if (this.basis === 'excess') { return v - PROSPERITY_BASELINE }
        return v
    }

    igProsperityKey(igId) {
        return 'prosperity_' + String(igId).toLowerCase()
    }

    blocksMatching(state, scope, target) {
        if (!state || !state.blocks) { return [] }
        if (scope === 'block') {
            return state.blocks.filter(function(b) { return b.id === target })
        }
        if (scope === 'stratum') {
            return state.blocks.filter(function(b) { return b.demographic.id === target })
        }
        if (scope === 'district') {
            return state.blocks.filter(function(b) { return b.district.id === target })
        }
        return []
    }

    weightedBlockProsperity(blocks) {
        var popSum = 0
        var weighted = 0
        for (var i = 0; i < blocks.length; i++) {
            var b = blocks[i]
            var pop = b.population
            if (pop <= 0) { continue }
            popSum += pop
            weighted += pop * (b.prosperity ?? PROSPERITY_BASELINE)
        }
        return popSum > 0 ? weighted / popSum : PROSPERITY_BASELINE
    }

    readBroadcastSource(state, q) {
        if (this.fromScope === 'quality') {
            var raw = Number(q[this.fromTarget])
            if (isNaN(raw)) { raw = PROSPERITY_BASELINE }
            return this.basisAmount(raw)
        }
        if (this.fromScope === 'ig') {
            var key = this.igProsperityKey(this.fromTarget)
            var igVal = q[key]
            if (igVal == null) { igVal = PROSPERITY_BASELINE }
            return this.basisAmount(igVal)
        }
        var blocks = this.blocksMatching(state, this.fromScope, this.fromTarget)
        return this.basisAmount(this.weightedBlockProsperity(blocks))
    }

    accumulate(state, q, blockDeltas, igDeltas) {
        if (!this.isActive(q)) { return }
        var mult = this.stacksFromQ(q)
        if (mult <= 0) { return }

        if (this.self_feedback) {
            this.accumulateSelfFeedback(state, q, blockDeltas, igDeltas, mult)
            return
        }

        var sourceSignal = this.readBroadcastSource(state, q)
        var transfer = this.coefficient * sourceSignal * mult
        if (transfer === 0) { return }

        if (this.toScope === 'ig') {
            var igKey = this.igProsperityKey(this.toTarget)
            igDeltas[igKey] = (igDeltas[igKey] || 0) + transfer
            return
        }

        var targets = this.blocksMatching(state, this.toScope, this.toTarget)
        for (var t = 0; t < targets.length; t++) {
            var id = targets[t].id
            blockDeltas[id] = (blockDeltas[id] || 0) + transfer
        }
    }

    accumulateSelfFeedback(state, q, blockDeltas, igDeltas, mult) {
        if (this.toScope === 'ig') {
            var igKey = this.igProsperityKey(this.toTarget)
            var igVal = q[igKey]
            if (igVal == null) { igVal = PROSPERITY_BASELINE }
            var igTransfer = this.coefficient * this.basisAmount(igVal) * mult
            if (igTransfer !== 0) {
                igDeltas[igKey] = (igDeltas[igKey] || 0) + igTransfer
            }
            return
        }

        var targets = this.blocksMatching(state, this.toScope, this.toTarget)
        for (var t = 0; t < targets.length; t++) {
            var block = targets[t]
            var fromBlocks = this.blocksMatching(state, this.fromScope, this.fromTarget)
            var matchesFrom = false
            for (var f = 0; f < fromBlocks.length; f++) {
                if (fromBlocks[f].id === block.id) {
                    matchesFrom = true
                    break
                }
            }
            if (!matchesFrom) { continue }
            var selfTransfer = this.coefficient * this.basisAmount(block.prosperity) * mult
            if (selfTransfer !== 0) {
                blockDeltas[block.id] = (blockDeltas[block.id] || 0) + selfTransfer
            }
        }
    }
}

function clampProsperity(value) {
    return Math.max(PROSPERITY_CLAMP_MIN, Math.min(PROSPERITY_CLAMP_MAX, value))
}

/**
 * One-shot citywide prosperity grants per stratum via Q.<stratum>_bump (e.g. coop_bump).
 * Adds bump to every voter block in that class, clamps, syncs Q, then sets the key to 0.
 * Cards:  on-arrival: coop_bump = 0.05
 * Same month: call Q.applyStratumProsperityBumps() in on-arrival after setting bump.
 * Otherwise applied at the start of monthly_tick_phase1 (before connection bleed).
 */
function applyStratumProsperityBumps() {
    var state = Q.electionV2
    if (!state || !state.blocks) { return false }

    var strata = Q.stratum_labels || [
        'rich', 'first', 'second', 'coop', 'drone', 'alien', 'deeper', 'third_wave',
    ]
    var changed = false

    for (var s = 0; s < strata.length; s++) {
        var sid = strata[s]
        var key = sid + '_bump'
        var raw = Q[key]
        if (raw == null || raw === 0) {
            Q[key] = 0
            continue
        }
        var bump = Number(raw)
        Q[key] = 0
        if (isNaN(bump) || bump === 0) { continue }

        for (var i = 0; i < state.blocks.length; i++) {
            var block = state.blocks[i]
            if (block.demographic.id !== sid) { continue }
            block.prosperity = clampProsperity(
                (block.prosperity ?? PROSPERITY_BASELINE) + bump
            )
        }
        changed = true
    }

    if (changed && typeof Q.qified_block_prosperity === 'function') {
        Q.qified_block_prosperity()
    }
    return changed
}

function applyProsperityConnections() {
    var state = Q.electionV2
    if (!state || !state.blocks || !Q.prosperityConnectionCatalog) { return }

    initEconomyProsperity()

    var blockDeltas = {}
    var igDeltas = {}
    var catalog = Q.prosperityConnectionCatalog

    for (var i = 0; i < catalog.length; i++) {
        catalog[i].accumulate(state, Q, blockDeltas, igDeltas)
    }

    for (var b = 0; b < state.blocks.length; b++) {
        var block = state.blocks[b]
        var delta = blockDeltas[block.id]
        if (delta) {
            block.prosperity = clampProsperity((block.prosperity ?? PROSPERITY_BASELINE) + delta)
        }
    }

    for (var igKey in igDeltas) {
        if (!Object.prototype.hasOwnProperty.call(igDeltas, igKey)) { continue }
        var igVal = Q[igKey]
        if (igVal == null) { igVal = PROSPERITY_BASELINE }
        Q[igKey] = clampProsperity(igVal + igDeltas[igKey])
    }

    if (typeof Q.qified_block_prosperity === 'function') {
        Q.qified_block_prosperity()
    }
}

Q.ProsperityConnectionModifier = ProsperityConnectionModifier

// id | from | to | coefficient — basis/self_feedback/stackId in opts; tune in economic_tick_planning.md
Q.prosperityConnectionCatalog = [
    // Stratum self-decay: 2% of local level per month (fixed point at 1.0)
    new ProsperityConnectionModifier('decay_rich', 'stratum', 'rich', 'stratum', 'rich', -0.02, { self_feedback: true }),
    new ProsperityConnectionModifier('decay_first', 'stratum', 'first', 'stratum', 'first', -0.02, { self_feedback: true }),
    new ProsperityConnectionModifier('decay_second', 'stratum', 'second', 'stratum', 'second', -0.02, { self_feedback: true }),
    new ProsperityConnectionModifier('decay_coop', 'stratum', 'coop', 'stratum', 'coop', -0.02, { self_feedback: true }),
    new ProsperityConnectionModifier('decay_drone', 'stratum', 'drone', 'stratum', 'drone', -0.02, { self_feedback: true }),
