]

/** Internal prosperity (1.0 = baseline). Cards/ticks adjust these; displays derived below. */
function initEconomyProsperity() {
    if (Q.prosperity_soylent !== undefined) { return }
    Q.prosperity_soylent = 1
    Q.prosperity_magrail = 1
    Q.prosperity_brazos = 1
    Q.prosperity_families = 1
    Q.prosperity_edges = 1
    Q.prosperity_sharks = 1
}

/** Map prosperity → Status / Society tab indicators (see economic_tick_planning.md). */
