// --- utilities ----------------------------------------------------------------

const sum = (nums) => nums.reduce((a, b) => a + b, 0)

const zeroPartyVotes = () => ({ D: 0, I: 0, C: 0, G: 0, H: 0 })

function assign_percentages(rawByParty, nSeats) {
    const raw = PARTY_KEYS.map((k) => rawByParty[k] || 0)
    const total = sum(raw)
    if (total === 0 || nSeats === 0) {
        return Object.fromEntries(PARTY_KEYS.map((k) => [k, 0]))
    }
    const votesPerSeat = total / nSeats
    const remainders = raw.map((v) => v % votesPerSeat)
    const whole = raw.map((v, i) => (v - remainders[i]) / votesPerSeat)
    let unassigned = nSeats - sum(whole.map(Math.floor))
    const rem = remainders.slice()
    for (let i = 0; i < unassigned; i++) {
        const idx = rem.reduce((best, x, j, arr) => (x > arr[best] ? j : best), 0)
        whole[idx] += 1
        rem[idx] = 0
    }
    return Object.fromEntries(PARTY_KEYS.map((k, i) => [k, Math.round(whole[i])]))
}

function formatSeatChange(delta) {
    if (delta > 0) { return '+' + delta }
    if (delta < 0) { return String(delta) }
    return '0'
}

/** Expose district election results as Q qualities for [+ … +] in scene prose (see scheduled_elections). */
function publishDistrictElectionReport(did, votes, oldSeats, newSeats) {
    const pct = votesToPollPercents(votes || zeroPartyVotes())
    Q['election_show_' + did] = 1
    for (const k of PARTY_KEYS) {
        Q[did + '_ev_' + k + '_pct'] = pct[k]
        Q[did + '_ev_' + k + '_seats'] = newSeats[k] || 0
        Q[did + '_ev_' + k + '_chg'] = formatSeatChange(
            (newSeats[k] || 0) - (oldSeats[k] || 0)
        )
    }
}

/** One-quarter guild turnover: 3 parts held seats, 1 part current poll (largest remainder). */
function rotateGuildSeatsQuarter(currentSeats, pollVotes, nSeats) {
    const rotate = Math.ceil(nSeats / 4)
    const keep = nSeats - rotate
    const mass = zeroPartyVotes()
    for (const k of PARTY_KEYS) {
        mass[k] = (currentSeats[k] || 0) * keep + (pollVotes[k] || 0) * rotate
    }
    return assign_percentages(mass, nSeats)
}

function softmax(scores, temperature = 1) {
    const keys = PARTY_KEYS
    const exps = keys.map((k) => Math.exp((scores[k] || 0) / temperature))
    const total = sum(exps) || 1
    return Object.fromEntries(keys.map((k, i) => [k, exps[i] / total]))
}

/** Legacy vote-label appeals (Dems, Corp, …) → competitive logit scale. */
const APPEAL_TO_SCORE = 0.05

function applyAppealsTo(target, labels, values) {
    for (let i = 0; i < labels.length; i++) {
        target[labels[i]] = values[i] || 0
    }
}

function voteLabelAppealsToScores(entity) {
    const scores = zeroPartyVotes()
    for (const [label, party] of Object.entries(VOTE_TO_PARTY)) {
        scores[party] = (entity[label] || 0) * APPEAL_TO_SCORE
    }
    return scores
}

function syncVoteAppealsToCompetitive(entity) {
    const base = entity._baseCompetitiveScores || zeroPartyVotes()
    const fromAppeals = voteLabelAppealsToScores(entity)
    entity.competitiveScores = {}
    for (const k of PARTY_KEYS) {
        entity.competitiveScores[k] = (base[k] || 0) + (fromAppeals[k] || 0)
    }
}

function syncGlobalVoteAppeals(state, labels, shifts) {
    const base = state._baseGlobalScores || zeroPartyVotes()
    const row = Object.fromEntries(labels.map((l, i) => [l, shifts[i] || 0]))
    const fromAppeals = voteLabelAppealsToScores(row)
    state.global.competitiveScores = {}
    for (const k of PARTY_KEYS) {
        state.global.competitiveScores[k] = (base[k] || 0) + (fromAppeals[k] || 0)
    }
}

function syncAllVoteAppeals(stratums, state, labels, globalShifts) {
    for (const s of stratums) {
        syncVoteAppealsToCompetitive(s)
    }
    if (state) {
        syncGlobalVoteAppeals(state, labels, globalShifts)
    }
}

