if (typeof Q.initEconomicAssets === 'function') { Q.initEconomicAssets() }
economic_assets_runtime_ready = 1

!}
go-to: post_event if economic_assets_bootstrap_return = 1; root.2300_main_continue if economic_assets_bootstrap_return = 2; post_event
`

fs.writeFileSync(runtimePath, runtimeScene)

const qAssignRe = /\nQ\.ensureEconomicAssets[\s\S]*?Q\.renderEconomicAssetsReport = renderEconomicAssetsReport\n/
let newTick = tick.slice(0, catalogStart) + RUNTIME_STUB + '\n\n' + tick.slice(monthlyTick)
newTick = newTick.replace(qAssignRe, '\n')
if (newTick.includes(CATALOG_BEGIN)) {
    console.error('sync-economic-runtime: failed to remove economic block from organize_phase_tick')
    process.exit(1)
}

fs.writeFileSync(tickPath, newTick)
console.log('sync-economic-runtime: wrote economic_assets_runtime.scene.dry and trimmed organize_phase_tick')

