#!/usr/bin/env node
/**
 * Scan on-arrival assignments in .dry scenes (outside {! !}) and ensure each
 * stack id has a placeholder row in Q.electorateModifierCatalog (delta 0).
 *
 * Usage:
 *   node scripts/sync-electorate-modifiers.js
 *   node scripts/sync-electorate-modifiers.js --check   # exit 1 if updates needed
 *   node scripts/sync-electorate-modifiers.js --dry-run
 */

const fs = require('fs')
const path = require('path')

const ROOT = path.join(__dirname, '..')
const SOURCE_DIR = path.join(ROOT, 'source', 'scenes')
const CATALOG_FILE = path.join(ROOT, 'source', 'scenes', 'electorate_runtime.scene.dry')

const SCOPES = new Set(['stratum', 'district', 'global'])
const PARTY_KEYS = new Set(['D', 'I', 'C', 'G', 'H'])
const AUTO_MARKER = '// --- auto-synced electorate stacks (delta 0) ---'
const REF_MARKER = '// --- Reference only:'

const RESERVED = new Set([
    'if', 'and', 'or', 'not', 'true', 'false', 'TBD',
    'Q', 'window', 'typeof', 'return', 'function', 'var', 'new',
])

/** Bump or set a stack on arrival (numeric RHS only for `=`). */
const STACK_BUMP_RE = /^([a-z][a-z0-9_]*)\s*(?:\+=|-=)/i
const STACK_SET_NUM_RE =
    /^([a-z][a-z0-9_]*)\s*=(?!=)\s*[-+]?(?:\d+\.?\d*|\.\d+)(?:[eE][-+]?\d+)?(?:\s*\/\s*[-+]?(?:\d+\.?\d*|\.\d+))?\s*$/i

const EXCLUDE_NAMES = new Set([
    'month_actions',
    'next_election_month',
    'next_election_year',
    'next_election_time',
    'phase',
    'organizing_unlock',
    'coalition_dissent',
    'shuffle_cabinet_timer',
])

const ADVISOR_TAG = 'advisor'

function sceneHasTag(fileText, tag) {
    for (const line of fileText.split(/\r?\n/).slice(0, 80)) {
        const m = line.match(/^tags:\s*(.+)/i)
        if (!m) { continue }
        const tags = m[1].split(',').map((t) => t.trim().toLowerCase())
        return tags.includes(tag.toLowerCase())
    }
    return false
}

/** Only the on-arrival segment on this line (stop at first `{!`). */
function onArrivalPayloadFromLine(line) {
    const trimmed = line.trim()
    if (!/^on-arrival:/i.test(trimmed)) { return null }
    let payload = trimmed.replace(/^on-arrival:\s*/i, '')
    const magic = payload.indexOf('{!')
    if (magic !== -1) {
        payload = payload.slice(0, magic)
    }
    payload = payload.trim()
    if (!payload) { return null }
    return payload
}

function walkDryFiles(dir, out = []) {
    for (const ent of fs.readdirSync(dir, { withFileTypes: true })) {
        const p = path.join(dir, ent.name)
        if (ent.isDirectory()) {
            walkDryFiles(p, out)
        } else if (ent.name.endsWith('.dry')) {
            out.push(p)
        }
    }
    return out
}

function considerStackName(name, found) {
    if (RESERVED.has(name)) { return }
    if (EXCLUDE_NAMES.has(name)) { return }
    if (name.endsWith('_TBD')) { return }
    if (name.endsWith('_toggle')) { return }
    found.add(name)
}

/** One statement (no trailing `if …` conditional). */
function extractFromStatement(stmt, found) {
    const s = stmt.trim()
    if (!s) { return }
    let m = STACK_BUMP_RE.exec(s)
    if (m) {
        considerStackName(m[1], found)
        return
    }
    m = STACK_SET_NUM_RE.exec(s)
    if (m) {
        considerStackName(m[1], found)
    }
}

function extractAssignmentTargets(text) {
    const found = new Set()
    for (const raw of text.split(';')) {
        const stmt = raw.split(/\s+if\s+/i)[0].trim()
        extractFromStatement(stmt, found)
    }
    return found
}

function extractStacksFromOnArrival(filePath) {
    const text = fs.readFileSync(filePath, 'utf8')
    if (sceneHasTag(text, ADVISOR_TAG)) {
        return new Set()
    }

    const stacks = new Set()
    for (const line of text.split(/\r?\n/)) {
        const payload = onArrivalPayloadFromLine(line)
        if (!payload) { continue }
        for (const name of extractAssignmentTargets(payload)) {
            stacks.add(name)
        }
    }
    return stacks
}

function parseStackIdFromLine(line) {
    const parts = [...line.matchAll(/'([^']*)'/g)].map((m) => m[1])
    if (parts.length < 2) { return null }
    if (SCOPES.has(parts[1])) { return parts[0] }
    if (parts.length >= 3 && SCOPES.has(parts[2])) { return parts[1] }
    return parts[0]
}

function parseCatalogStackIds(catalogText) {
    const active = catalogText.split(REF_MARKER)[0]
    const ids = new Set()
    for (const line of active.split(/\r?\n/)) {
        if (!line.includes('new ElectorateModifier')) { continue }
        const stackId = parseStackIdFromLine(line)
        if (stackId) { ids.add(stackId) }
    }
    return ids
}

function formatPlaceholder(stackId) {
    return `    new ElectorateModifier('${stackId}_auto', '${stackId}', 'global', '', 'D', 0),`
}

function upsertCatalog(newStacks) {
    const text = fs.readFileSync(CATALOG_FILE, 'utf8')
    const existing = parseCatalogStackIds(text)
    const missing = [...newStacks].filter((s) => !existing.has(s)).sort()
    if (missing.length === 0) {
        return { changed: false, missing: [], text }
    }

    const lines = missing.map((s) => formatPlaceholder(s))
    let updated = text

    if (updated.includes(AUTO_MARKER)) {
        const insertAt = updated.indexOf(AUTO_MARKER) + AUTO_MARKER.length
        updated =
            updated.slice(0, insertAt)
            + '\n'
            + lines.join('\n')
            + updated.slice(insertAt)
    } else {
        const anchor = REF_MARKER
        const idx = updated.indexOf(anchor)
        const block =
            '\n\n    '
            + AUTO_MARKER
            + '\n'
            + lines.join('\n')
            + '\n'
        if (idx !== -1) {
            updated = updated.slice(0, idx) + block + updated.slice(idx)
        } else {
            updated = updated.replace(
                /(\n\])\s*(\n\nQ\.applyElectorateModifiers)/,
                block + '\n$1$2'
            )
        }
    }

    return { changed: true, missing, text: updated }
}

function collectAllStacks() {
    const files = walkDryFiles(SOURCE_DIR).filter(
        (f) => path.normalize(f) !== path.normalize(CATALOG_FILE)
    )
    const all = new Set()
    for (const file of files) {
        for (const s of extractStacksFromOnArrival(file)) {
            all.add(s)
        }
    }
    return all
}

function main() {
    const check = process.argv.includes('--check')
    const dryRun = process.argv.includes('--dry-run')
    const stacks = collectAllStacks()
    const { changed, missing, text } = upsertCatalog(stacks)

    if (missing.length === 0) {
        console.log('electorate stacks: catalog is up to date')
        process.exit(0)
    }

    console.log(`electorate stacks: adding ${missing.length} placeholder(s):`)
    for (const s of missing) {
        console.log(`  - ${s}`)
    }

    if (check) {
        process.exit(1)
    }
    if (!dryRun) {
        fs.writeFileSync(CATALOG_FILE, text, 'utf8')
        console.log(`updated ${path.relative(ROOT, CATALOG_FILE)}`)
    }
    process.exit(0)
}

main()

#!/usr/bin/env node
/**
 * Run the Mikasa election model without Dendrynexus.
 *
 * Usage:
 *   node scripts/simulate-election.js              # v1 (legacy voter-block model)
 *   node scripts/simulate-election.js --v2       # v2 (IG floor + competitive)
 *   node scripts/simulate-election.js --v2 --scenario democratic_awakening
 *   node scripts/simulate-election.js --json
 */

const path = require('path')

const args = process.argv.slice(2)
const jsonOut = args.includes('--json')
const useV2 = args.includes('--v2')
const fromScene = args.includes('--from-scene')
const igOnly = args.includes('--ig-tabulation')
const noIgTab = args.includes('--no-ig-tabulation')
const igDistrict = args.includes('--ig-tabulation-district')
const igFull = args.includes('--ig-tabulation-full')
const help = args.includes('--help') || args.includes('-h')

const igFilterIdx = args.indexOf('--ig')
const igFilter = igFilterIdx >= 0 ? args[igFilterIdx + 1] : null

const scenarioIdx = args.indexOf('--scenario')
const scenario = scenarioIdx >= 0 ? args[scenarioIdx + 1] : 'baseline'

if (help) {
    console.log(`Usage: node scripts/simulate-election.js [options]

  (default)     v1 model (source/lib/election-model.js)
  --v2          v2 model: demo×district blocks, corp/syndicate IGs + competitive vote
  --from-scene  v2 only: load MIKASA_* runtime blocks from election + electorate scenes
  --scenario S  v2 only: ${Object.keys(require(path.join(__dirname, '../source/lib/election-v2.js')).SCENARIOS).join(', ')}
  --json        JSON output
  --ig-tabulation           v2: only IG→VoterBlock source tables (executive chamber)
  --ig-tabulation-full      v2: all VoterBlocks per IG + list of zero-contribution blocks
  --ig-tabulation-district  v2: also show district-chamber IG sources in full report
  --no-ig-tabulation        v2: omit IG source tables from default report
  --ig ID                 v2: only one interest group (e.g. --ig Soylent)
`)
    process.exit(0)
}

if (useV2) {
    const v2 = require(path.join(__dirname, '../source/lib/election-v2.js'))
    let Q
    if (fromScene) {
        const { loadSceneOnArrival } = require(path.join(__dirname, 'extract-scene-js.js'))
        const scenePath = path.join(__dirname, '../source/scenes/election_runtime.scene.dry')
        Q = loadSceneOnArrival(scenePath)
        if (scenario !== 'baseline') {
            v2.applyScenario(Q.electionV2, scenario)
            Q.update_projections({ allDistricts: true })
        }
    } else {
        ;({ Q } = v2.initElectionV2({}, {
            scenario,
            allDistricts: true,
            includeZeroBlocks: igFull,
        }))
    }
    const reportOpts = {
        includeIgTabulation: !noIgTab,
        includeDistrictIgTabulation: igDistrict,
        includeZeroBlocks: igFull,
        igFilter: igFilter,
        maxRowsPerIg: igFull ? Infinity : 15,
    }
    if (jsonOut) {
        console.log(JSON.stringify(v2.electionSnapshotV2(Q), null, 2))
    } else if (igOnly) {
        const tab = Q.electionV2.igTabulation.executive
        console.log(v2.formatIgBlockTabulation(tab, reportOpts))
        if (igDistrict) {
            console.log(v2.formatIgBlockTabulation(Q.electionV2.igTabulation.district, reportOpts))
        }
    } else {
        console.log(v2.formatElectionReportV2(Q, null, reportOpts))
    }
} else {
    const v1 = require(path.join(__dirname, '../source/lib/election-model.js'))
    const { Q } = v1.initElectionModel()
    Q.electorate.assign_seats()
    Q.qified_pops()
    if (jsonOut) {
        console.log(JSON.stringify(v1.electionSnapshot(Q), null, 2))
    } else {
        console.log(v1.formatElectionReport(Q))
    }
}

