            }
        }
    }
    return blocks
}

// --- tabulation ---------------------------------------------------------------

function blockCompetitiveScores(block, state) {
    const scores = zeroPartyVotes()
    for (const k of PARTY_KEYS) {
        scores[k] =
            (block.demographic.competitiveScores[k] || 0)
            + (block.district.competitiveScores[k] || 0)
            + (block.competitiveScores[k] || 0)
            + (state.global.competitiveScores[k] || 0)
    }
    return scores
}

function blockSteepness(block) {
    const out = {}
    for (const k of PARTY_KEYS) {
        out[k] =
            (block.demographic.competitiveSteepness[k] || 1)
            * (block.competitiveSteepness[k] || 1)
    }
    return out
}

/** Sum of IG membership shares for this block, capped by demographic igClaimCap. */
function claimedFraction(block, interestGroups, chamber) {
    const igs = interestGroups.filter((ig) => chamber.igKinds.includes(ig.kind))
    let raw = sum(igs.map((ig) => ig.effectiveMembership(block)))
    return Math.min(raw, block.demographic.igClaimCap)
}

/**
 * Per–interest-group IG ballots from one VoterBlock (before party split).
 * @returns {{ contributions: Array, votes: object }}
 */
function igContributionsForBlock(block, interestGroups, chamber, state) {
    const votes = zeroPartyVotes()
    const contributions = []
    const igs = interestGroups.filter((ig) => chamber.igKinds.includes(ig.kind))
    const pop = block.population * VOTE_SCALE
    const cap = block.demographic.igClaimCap
    const rawShares = igs.map((ig) => ig.effectiveMembership(block))
    const rawTotal = sum(rawShares) || 1
    const scale = rawTotal > cap ? cap / rawTotal : 1
    const turnoutMult =
        chamber.igTurnoutMult * (state.global.igTurnoutMult || 1)

    for (let i = 0; i < igs.length; i++) {
        const ig = igs[i]
        const rawShare = rawShares[i]
        const scaledShare = rawShare * scale
        const ballots = pop * scaledShare * ig.turnout * turnoutMult
        const igVotes = zeroPartyVotes()
        for (const k of PARTY_KEYS) {
            igVotes[k] = ballots * ig.partyShares[k]
            votes[k] += igVotes[k]
        }
        if (ballots <= 0 && rawShare <= 0) { continue }
        contributions.push({
            igId: ig.id,
            igKind: ig.kind,
            blockId: block.id,
            district: block.district.id,
            demographic: block.demographic.id,
            demographicLabel: STRATUM_DISPLAY[block.demographic.id] || block.demographic.id,
            population: block.population,
            rawMembership: rawShare,
            scaledMembership: scaledShare,
            ballots,
            votes: igVotes,
        })
    }
    return { contributions, votes }
}

function allocateIgVotes(block, interestGroups, chamber, state) {
    return igContributionsForBlock(block, interestGroups, chamber, state).votes
}

/**
 * Aggregate IG-determined ballots by interest group and source VoterBlock.
 * @param {object} state
 * @param {string} chamberId
 * @param {{ minBallots?: number }} options
 */
function buildIgBlockTabulation(state, chamberId = 'executive', options = {}) {
    const chamber = CHAMBERS[chamberId]
    const minBallots = options.minBallots ?? 1
    const byIg = {}

    for (const ig of state.interestGroups) {
        if (!chamber.igKinds.includes(ig.kind)) { continue }
        byIg[ig.id] = {
            igId: ig.id,
            igKind: ig.kind,
            partyShares: Object.assign({}, ig.partyShares),
            totalBallots: 0,
            totalVotes: zeroPartyVotes(),
            blocks: [],
            zeroBlocks: [],
        }
    }

    const includeZeroBlocks = options.includeZeroBlocks === true
    const igById = Object.fromEntries(
        state.interestGroups.map((ig) => [ig.id, ig])
    )

    for (const block of state.blocks) {
        const { contributions } = igContributionsForBlock(
            block, state.interestGroups, chamber, state
        )
        const contributedIg = new Set()
        for (const row of contributions) {
            if (row.ballots < minBallots) { continue }
            contributedIg.add(row.igId)
            const bucket = byIg[row.igId]
            if (!bucket) { continue }
            bucket.blocks.push(row)
            bucket.totalBallots += row.ballots
            for (const k of PARTY_KEYS) {
                bucket.totalVotes[k] += row.votes[k]
            }
        }
        if (includeZeroBlocks) {
            for (const igId of Object.keys(byIg)) {
                if (contributedIg.has(igId)) { continue }
                const ig = igById[igId]
                byIg[igId].zeroBlocks.push({
                    blockId: block.id,
                    district: block.district.id,
                    demographic: block.demographic.id,
                    demographicLabel:
                        STRATUM_DISPLAY[block.demographic.id] || block.demographic.id,
                    population: block.population,
                    rawMembership: ig ? ig.effectiveMembership(block) : 0,
                })
            }
        }
    }

    const blockSort = (a, b) =>
        a.district.localeCompare(b.district)
        || a.demographic.localeCompare(b.demographic)

    for (const igId of Object.keys(byIg)) {
        byIg[igId].blocks.sort((a, b) => b.ballots - a.ballots)
        if (includeZeroBlocks) {
            byIg[igId].zeroBlocks.sort(blockSort)
        }
    }

    return { chamberId, chamberLabel: chamberId, byIg }
}

function competitiveTurnout(block, chamber, state) {
    let t = chamber.competitiveTurnout * (state.global.competitiveTurnout || 1)
    t += block.district.competitiveTurnoutBonus || 0
    t += state.global.competitiveTurnoutBonus || 0
    if (t < 0.05) { t = 0.05 }
    if (t > 1) { t = 1 }
    return t
}

function allocateCompetitiveVotes(block, interestGroups, chamber, state) {
    const votes = zeroPartyVotes()
    const claimed = claimedFraction(block, interestGroups, chamber)
    const competitivePop = block.population * (1 - claimed) * VOTE_SCALE
    if (competitivePop <= 0) { return votes }

    let turnout = competitiveTurnout(block, chamber, state)
    // Low turnout helps gangs in syndicate turf (Pitts)
    if (block.district.lowTurnoutGangBonus && turnout < 0.45) {
        state._gangLowTurnoutBoost = block.district.lowTurnoutGangBonus
    }

    const scores = blockCompetitiveScores(block, state)
    const steep = blockSteepness(block)
    const weighted = {}
    for (const k of PARTY_KEYS) {
        let s = (scores[k] || 0) * (steep[k] || 1)
        if (k === 'G' && state._gangLowTurnoutBoost) {
            s += state._gangLowTurnoutBoost
        }
        weighted[k] = s
    }
    state._gangLowTurnoutBoost = 0

    const shares = softmax(weighted, state.global.softmaxTemperature || 1)
    const ballots = competitivePop * turnout
    for (const k of PARTY_KEYS) {
        votes[k] += ballots * shares[k]
    }
    return votes
}

/** Non-Corp ballots abstain (not counted); Corp (C) unchanged. */
function corpOrAbstainPartyVotes(votes) {
    const out = zeroPartyVotes()
    out.C = votes.C || 0
    return out
}

function sumPartyVoteObjects(a, b) {
    const out = zeroPartyVotes()
    for (const k of PARTY_KEYS) {
        out[k] = (a[k] || 0) + (b[k] || 0)
    }
    return out
}

/** Megacorp drone contracts: competitive and IG splits may only add Corp votes; all else abstains. */
/** TODO: when the corporations have three different parties, the drones will be restricted for
their own employer, potentially allowing lower turnout for one corporation then another */
function applyDroneCorpOrAbstainRule(block, result, state, chamber) {
    if (block.demographic.voteRule !== 'corp_or_abstain') { return result }
    result.ig = corpOrAbstainPartyVotes(result.ig)
    result.comp = corpOrAbstainPartyVotes(result.comp)
    result.total = sumPartyVoteObjects(result.ig, result.comp)
    return result
}

const BLOCK_VOTE_RULES = [
    applyDroneCorpOrAbstainRule,
]

function applyBlockVoteRules(block, result, state, chamber) {
    for (let r = 0; r < BLOCK_VOTE_RULES.length; r++) {
        result = BLOCK_VOTE_RULES[r](block, result, state, chamber) || result
    }
    return result
}

function tabulateBlockWithAbstention(block, interestGroups, chamber, state) {
    const ig = allocateIgVotes(block, interestGroups, chamber, state)
    const comp = allocateCompetitiveVotes(block, interestGroups, chamber, state)
    const preRule = sumPartyVoteObjects(ig, comp)
    let result = {
        ig,
        comp,
        total: preRule,
    }
    result = applyBlockVoteRules(block, result, state, chamber)
    const weight = chamber.useExecutiveWeight ? block.demographic.executiveWeight : 1
    let ballotMass = sum(PARTY_KEYS.map((k) => preRule[k] || 0))
    let countedMass = sum(PARTY_KEYS.map((k) => result.total[k] || 0))
    if (weight !== 1) {
        ballotMass *= weight
        for (const k of PARTY_KEYS) {
            result.total[k] = (result.total[k] || 0) * weight
        }
        countedMass = sum(PARTY_KEYS.map((k) => result.total[k] || 0))
    }
    return {
        ig: result.ig,
        comp: result.comp,
        total: result.total,
        ballotMass,
        countedMass,
        abstentionMass: Math.max(0, ballotMass - countedMass),
    }
}

function tabulateBlock(block, interestGroups, chamber, state) {
    const t = tabulateBlockWithAbstention(block, interestGroups, chamber, state)
    return { ig: t.ig, comp: t.comp, total: t.total }
}

class ElectionEngineV2 {
    constructor(state) {
        this.state = state
    }

    runChamber(chamberId, options = {}) {
        const chamber = CHAMBERS[chamberId]
        const { interestGroups, blocks, districts } = this.state
        const totals = zeroPartyVotes()
        const byDistrict = {}
        const byGuild = { Gold: zeroPartyVotes(), White: zeroPartyVotes(), Blue: zeroPartyVotes() }

        const activeBlocks =
            options.districtId
                ? blocks.filter((b) => b.district.id === options.districtId)
                : blocks

        for (const block of activeBlocks) {
            const { ig, comp, total } = tabulateBlock(
                block, interestGroups, chamber, this.state
            )
            for (const k of PARTY_KEYS) {
                totals[k] += total[k]
            }
            if (chamber.elects === 'perDistrict') {
                const d = block.district.id
                if (!byDistrict[d]) { byDistrict[d] = zeroPartyVotes() }
                for (const k of PARTY_KEYS) {
                    byDistrict[d][k] += total[k]
                }
            }
            if (chamber.elects === 'perGuild') {
                for (const igroup of interestGroups) {
                    if (igroup.kind !== 'guild' || !igroup.guildSeatKey) { continue }
                    const mem = igroup.effectiveMembership(block) * block.population * VOTE_SCALE
                    for (const k of PARTY_KEYS) {
                        byGuild[igroup.guildSeatKey][k] += mem * igroup.partyShares[k]
                    }
                }
            }
        }

        if (chamber.elects === 'global') {
            return { votes: totals, seats: assign_percentages(totals, chamber.seats) }
        }
        if (chamber.elects === 'perDistrict') {
            const seats = {}
            for (const d of Object.keys(byDistrict)) {
                seats[d] = assign_percentages(byDistrict[d], chamber.seats)
            }
            return { byDistrict, seats }
        }
        if (chamber.elects === 'perGuild') {
            const seats = {}
            for (const g of ['Gold', 'White', 'Blue']) {
                seats[g] = assign_percentages(byGuild[g], chamber.seats)
            }
            return { byGuild, seats }
        }
        return { votes: totals }
    }

    runAll(options = {}) {
        const month = options.month ?? 1
        const results = {
            executive: this.runChamber('executive'),
            guild: this.runChamber('guild'),
            districts: {},
        }
        for (const district of this.state.districts) {
            if (district.electionMonth === month || options.allDistricts) {
                results.districts[district.id] = this.runChamber('district', {
                    districtId: district.id,
                })
            }
        }
        return results
    }

    writeToQ(Q, results) {
        const ex = results.executive.seats
        for (const k of PARTY_KEYS) {
            Q['Exec_' + k] = ex[k]
        }
        for (const g of ['Gold', 'White', 'Blue']) {
            const seats = results.guild.seats[g]
            for (const k of PARTY_KEYS) {
                Q[g + '_' + k] = seats[k]
            }
        }
        for (const d of DISTRICT_IDS) {
            const run = results.districts[d]
            if (!run) { continue }
            const seats = run.seats[d]
            for (const k of PARTY_KEYS) {
                Q[d + '_' + k] = seats[k]
            }
        }
    }
}

function votesToPollPercents(votes) {
    const total = sum(PARTY_KEYS.map((k) => votes[k] || 0))
    const out = {}
    for (const k of PARTY_KEYS) {
        out[k] = total > 0 ? Math.round(((votes[k] || 0) / total) * 1000) / 10 : 0
    }
    return out
}

/** Popular-vote shares for status polls tab (district / general-electorate model). */
function writePollDisplaysToQ(Q, state, results) {
    const chamber = CHAMBERS.district
    const citywide = zeroPartyVotes()
    for (const did of DISTRICT_IDS) {
        const run = results.districts[did]
        if (run && run.byDistrict && run.byDistrict[did]) {
            for (const k of PARTY_KEYS) {
                citywide[k] += run.byDistrict[did][k] || 0
            }
        }
    }
    if (sum(PARTY_KEYS.map((k) => citywide[k])) === 0) {
        for (const block of state.blocks) {
            const { total } = tabulateBlock(
                block, state.interestGroups, chamber, state
            )
            for (const k of PARTY_KEYS) {
                citywide[k] += total[k] || 0
            }
        }
    }
    const cityPct = votesToPollPercents(citywide)
    for (const k of PARTY_KEYS) {
        Q['poll_exec_' + k] = cityPct[k]
    }
    const byStratum = {}
    for (const sid of STRATUM_IDS) {
        byStratum[sid] = zeroPartyVotes()
    }
    for (const block of state.blocks) {
        const { total } = tabulateBlock(
            block, state.interestGroups, chamber, state
        )
        const sid = block.demographic.id
        for (const k of PARTY_KEYS) {
            byStratum[sid][k] += total[k] || 0
        }
    }
    for (const sid of STRATUM_IDS) {
        if (sid === 'drone') { continue }
        const pct = votesToPollPercents(byStratum[sid] || zeroPartyVotes())
        for (const k of PARTY_KEYS) {
            Q[sid + '_poll_' + k] = pct[k]
        }
    }
    let droneBallotMass = 0
    let droneCorpMass = 0
    let droneAbstainMass = 0
    for (const block of state.blocks) {
        if (block.demographic.id !== 'drone') { continue }
        const t = tabulateBlockWithAbstention(
            block, state.interestGroups, chamber, state
        )
        droneBallotMass += t.ballotMass
        droneCorpMass += t.total.C || 0
        droneAbstainMass += t.abstentionMass
    }
    const dronePct = (mass) =>
        droneBallotMass > 0 ? Math.round((mass / droneBallotMass) * 1000) / 10 : 0
    Q.drone_poll_C = dronePct(droneCorpMass)
    Q.drone_poll_abstain = dronePct(droneAbstainMass)
    for (const k of PARTY_KEYS) {
        if (k !== 'C') {
            Q['drone_poll_' + k] = 0
        }
    }
    for (const did of DISTRICT_IDS) {
        let votes = zeroPartyVotes()
        const run = results.districts[did]
        if (run && run.byDistrict && run.byDistrict[did]) {
            votes = run.byDistrict[did]
        } else {
            for (const block of state.blocks) {
                if (block.district.id !== did) { continue }
                const { total } = tabulateBlock(
                    block, state.interestGroups, chamber, state
                )
                for (const k of PARTY_KEYS) {
                    votes[k] += total[k] || 0
                }
            }
        }
        const pct = votesToPollPercents(votes)
        for (const k of PARTY_KEYS) {
            Q[did + '_poll_' + k] = pct[k]
        }
    }
}

function qified_pops(state) {
    for (const block of state.blocks) {
        Q[block.district.id + "_" + block.demographic.id + "_pop"] = block.population
    }
}

function qified_block_prosperity(state) {
    for (const block of state.blocks) {
        Q[block.district.id + "_" + block.demographic.id + "_prosperity"] = block.prosperity
    }
    syncStratumProsperityAverages(state)
}

/** Citywide population-weighted mean prosperity per stratum → Q.prosperity_<id>. */
function syncStratumProsperityAverages(state) {
    for (const sid of STRATUM_IDS) {
        let popSum = 0
        let weighted = 0
        for (const block of state.blocks) {
            if (block.demographic.id !== sid) { continue }
            const pop = block.population
            if (pop <= 0) { continue }
            popSum += pop
            weighted += pop * (block.prosperity ?? 1)
        }
        const avg = popSum > 0 ? weighted / popSum : 1
        Q['prosperity_' + sid] = Math.round(avg * 100) / 100
    }
}

Q.stratum_labels = STRATUM_IDS.slice()
Q.vote_labels = ["Dems", "Ind", "Corp", "Gang", "Hate", "Swing", "Apathy"]
Q.global_shifts = [0, -20, 0, -1, -3, 0, 0]
Q.lookups = {}
Q.stratums = []
Q.regions = []
Q.interests = []
Q.voter_blocks = []

const demographics = buildDemographics()
const districts = buildDistricts()
const interestGroups = buildInterestGroups()
Q.interest_labels = interestGroups.map((ig) => ig.id)
const blocks = buildVoterBlocks(demographics, districts)

const electionState = {
    demographics,
    districts,
    interestGroups,
    blocks,
    global: {
        competitiveTurnout: 1,
        igTurnoutMult: 1,
        competitiveTurnoutBonus: 0,
        competitiveScores: zeroPartyVotes(),
        softmaxTemperature: 1,
    },
}
electionState._baseGlobalScores = Object.assign({}, electionState.global.competitiveScores)

const engine = new ElectionEngineV2(electionState)

/** Held council seats (Exec_*, Gold_*, Docks_*, …) — only updated when commitSeats is true. */
function writeCommittedSeatsToQ(Q, results) {
    engine.writeToQ(Q, results)
}

/** Latest tabulation for election sim / debugging (Proj_*); refreshed every update_projections. */
function writeProjectionSeatsToQ(Q, results) {
    const ex = results.executive.seats
    for (const k of PARTY_KEYS) {
        Q['Proj_Exec_' + k] = ex[k]
    }
    for (const g of ['Gold', 'White', 'Blue']) {
        const seats = results.guild.seats[g]
        for (const k of PARTY_KEYS) {
            Q['Proj_' + g + '_' + k] = seats[k]
        }
    }
    for (const d of DISTRICT_IDS) {
        const run = results.districts[d]
        if (!run) { continue }
        const seats = run.seats[d]
        for (const k of PARTY_KEYS) {
            Q['Proj_' + d + '_' + k] = seats[k]
        }
    }
}

function runElectionsAndWriteQ(opts) {
    opts = opts || {}
    // Appeals first; story-stack modifiers add on top (see post_event applyElectorateModifiers).
    syncAllVoteAppeals(Q.stratums, electionState, Q.vote_labels, Q.global_shifts)
    if (typeof Q.applyElectorateModifiers === 'function') {
        Q.applyElectorateModifiers()
    }
    const results = engine.runAll({
        month: opts.month != null ? opts.month : (Q.month || 1),
        allDistricts: opts.allDistricts !== false,
    })
    if (opts.commitSeats) {
        writeCommittedSeatsToQ(Q, results)
    }
    writeProjectionSeatsToQ(Q, results)
    writePollDisplaysToQ(Q, electionState, results)
    qified_pops(electionState)
    qified_block_prosperity(electionState)
    Q.electionResults = results
    return results
}

Q.stratumDisplay = STRATUM_DISPLAY
Q.districtDisplay = DISTRICT_DISPLAY

runElectionsAndWriteQ({ allDistricts: true, commitSeats: false })

Q.electionV2 = electionState
Q.electionEngine = engine
Q.electorate = engine
Q.voter_blocks = blocks
Q.qified_pops = function() { qified_pops(electionState) }
Q.qified_block_prosperity = function() { qified_block_prosperity(electionState) }
Q.syncStratumProsperityAverages = function() { syncStratumProsperityAverages(electionState) }
Q.update_projections = function(opts) {
    return runElectionsAndWriteQ(Object.assign({ commitSeats: false }, opts || {}))
}
Q.assignSeatsFromInitialPolling = function() {
    return runElectionsAndWriteQ({ month: 1, allDistricts: true, commitSeats: true })
}
engine.assign_seats = function(opts) {
    return runElectionsAndWriteQ(Object.assign({ commitSeats: true }, opts || {}))
}

/**
 * Apply scheduled seat updates after month tick (current polling).
 * Guild: each month, 1/4 of seats reallocated silently (no election event).
 * Executive: full refresh in December. Districts: per DISTRICT_ELECTION_MONTH.
 */
Q.runScheduledElections = function(opts) {
    opts = opts || {}
    const month = opts.month != null ? opts.month : (Q.month || 1)
    const year = opts.year != null ? opts.year : (Q.year || 2300)
    const report = {
        month,
        year,
        skipped: false,
        executive: false,
        districts: [],
        any: false,
        lines: [],
    }

    if (
        !opts.force
        && !Q.elections_allow_same_month_repeat
        && Q.elections_applied_month === month
        && Q.elections_applied_year === year
    ) {
        report.skipped = true
        report.any = false
        for (const did of DISTRICT_IDS) {
            Q['election_show_' + did] = 0
        }
        return report
    }

    for (const did of DISTRICT_IDS) {
        Q['election_show_' + did] = 0
    }

    const results = runElectionsAndWriteQ({
        month,
        allDistricts: false,
        commitSeats: false,
    })

    for (const g of GUILD_KEYS) {
        const current = Object.fromEntries(
            PARTY_KEYS.map((k) => [k, Q[g + '_' + k] || 0])
        )
        const pollVotes = results.guild.byGuild[g] || zeroPartyVotes()
        const newSeats = rotateGuildSeatsQuarter(current, pollVotes, GUILD_SEATS)
        for (const k of PARTY_KEYS) {
            Q[g + '_' + k] = newSeats[k]
        }
    }

    if (month === EXEC_ELECTION_MONTH) {
        const ex = results.executive.seats
        for (const k of PARTY_KEYS) {
            Q['Exec_' + k] = ex[k]
        }
        report.executive = true
        report.lines.push('The Executive Council was re-elected for the coming year.')
    }

    for (const did of DISTRICT_IDS) {
        if (DISTRICT_ELECTION_MONTH[did] !== month) { continue }
        const run = results.districts[did]
        if (!run || !run.seats || !run.seats[did]) { continue }
        const oldSeats = Object.fromEntries(
            PARTY_KEYS.map((k) => [k, Q[did + '_' + k] || 0])
        )
        const ds = run.seats[did]
        const votes = run.byDistrict[did] || zeroPartyVotes()
        for (const k of PARTY_KEYS) {
            Q[did + '_' + k] = ds[k]
        }
        report.districts.push(did)
        publishDistrictElectionReport(did, votes, oldSeats, ds)
    }

    Q.elections_applied_month = month
    Q.elections_applied_year = year

    report.any = report.executive || report.districts.length > 0
    if (report.any) {
        Q.elections_this_month = 1
        Q.election_report = report.lines.join('\n\n')
    } else {
        Q.elections_this_month = 0
        Q.election_report = ''
    }
    return report
}

