#!/usr/bin/env node
/**
 * Extract JavaScript from Dendry runtime scenes for Node tests.
 * Authoritative logic lives in source/scenes (scene.dry) — not in source/lib.
 *
 * Runtime blocks live between marker comments in silent setup scenes:
 *   // MIKASA_ELECTION_RUNTIME_BEGIN … // MIKASA_ELECTION_RUNTIME_END
 *
 * Usage:
 *   node scripts/extract-scene-js.js election_runtime
 *   node scripts/extract-scene-js.js --list
 */

const fs = require('fs')
const path = require('path')

const ROOT = path.join(__dirname, '..')
const SCENES = path.join(ROOT, 'source', 'scenes')

/** blockName → scene file (relative to source/scenes) */
const RUNTIME_SCENES = {
    ELECTION_RUNTIME: 'election_runtime.scene.dry',
    ELECTORATE_RUNTIME: 'electorate_runtime.scene.dry',
    ECONOMIC_ASSETS_RUNTIME: 'economic_assets_runtime.scene.dry',
    ORGANIZING_RUNTIME: 'cards/organizing/organize_phase_tick.scene.dry',
}

function runtimeMarkers(blockName) {
    return {
        begin: `// MIKASA_${blockName}_BEGIN`,
        end: `// MIKASA_${blockName}_END`,
    }
}

function extractRuntimeBlock(text, blockName) {
    const { begin, end } = runtimeMarkers(blockName)
    const i = text.indexOf(begin)
    const j = text.indexOf(end)
    if (i < 0 || j < 0 || j <= i) {
        throw new Error(
            `extract-scene-js: missing ${begin} / ${end} markers`,
        )
    }
    return text.slice(i + begin.length, j).trim()
}

function extractRuntimeBlockFromFile(scenePath, blockName) {
    const text = fs.readFileSync(scenePath, 'utf8')
    return extractRuntimeBlock(text, blockName)
}

function resolveRuntimeScene(blockName) {
    const rel = RUNTIME_SCENES[blockName]
    if (!rel) {
        throw new Error(`extract-scene-js: unknown runtime block ${blockName}`)
    }
    return path.join(SCENES, rel)
}

function loadRuntimeBlock(blockName, options = {}) {
    const scenePath = resolveRuntimeScene(blockName)
    const js = extractRuntimeBlockFromFile(scenePath, blockName)
    const Q = options.Q || global.Q || {}
    global.Q = Q
    // eslint-disable-next-line no-eval
    eval(js)
    return Q
}

/** Load election + electorate (and optional extras) in bootstrap order. */
function loadGameRuntimes(options = {}) {
    const blocks = options.blocks || [
        'ELECTION_RUNTIME',
        'ELECTORATE_RUNTIME',
    ]
    let Q = options.Q || {}
    global.Q = Q
    for (const blockName of blocks) {
        loadRuntimeBlock(blockName, { Q })
        Q = global.Q
    }
    if (options.refreshProjections && typeof Q.update_projections === 'function') {
        Q.update_projections(options.projectionOpts || { allDistricts: true })
    }
    if (options.commitSeats && typeof Q.assignSeatsFromInitialPolling === 'function') {
        Q.assignSeatsFromInitialPolling()
    }
    return Q
}

/** Legacy: first on-arrival block (prefer extractRuntimeBlock). */
const ON_ARRIVAL_RE = /on-arrival:\s*\{!\s*([\s\S]*?)\s*!\}/

function extractOnArrivalJs(scenePath) {
    const text = fs.readFileSync(scenePath, 'utf8')
    const match = text.match(ON_ARRIVAL_RE)
    if (!match) {
        throw new Error(`extract-scene-js: no on-arrival block in ${scenePath}`)
    }
    return match[1].trim()
}

function loadSceneOnArrival(scenePath, options = {}) {
    const js = extractOnArrivalJs(scenePath)
    const Q = options.Q || {}
    global.Q = Q
    // eslint-disable-next-line no-eval
    eval(js)
    return Q
}

if (require.main === module) {
    if (process.argv.includes('--list')) {
        for (const [name, rel] of Object.entries(RUNTIME_SCENES)) {
            console.log(`${name}\t${rel}`)
        }
        process.exit(0)
    }
    const arg = process.argv[2]
    if (!arg) {
        console.error(
            'Usage: node scripts/extract-scene-js.js <BLOCK_NAME|--list>',
        )
        process.exit(1)
    }
    if (arg === 'game') {
        loadGameRuntimes({
            refreshProjections: true,
            commitSeats: true,
        })
        process.exit(0)
    }
    process.stdout.write(extractRuntimeBlockFromFile(resolveRuntimeScene(arg), arg))
}

module.exports = {
    RUNTIME_SCENES,
    runtimeMarkers,
    extractRuntimeBlock,
    extractRuntimeBlockFromFile,
    loadRuntimeBlock,
    loadGameRuntimes,
    extractOnArrivalJs,
    loadSceneOnArrival,
    ON_ARRIVAL_RE,
}

#!/usr/bin/env node
/**
 * Run monthly_tick_phase1 for N months in Node (prosperity mesh, housing, assets).
 *
 *   node scripts/simulate-prosperity-months.js
 *   node scripts/simulate-prosperity-months.js --months 6
 *   node scripts/simulate-prosperity-months.js --months 12 --verbose
 *   node scripts/simulate-prosperity-months.js --json
 *
 * Loads election + electorate + organizing tick + economic_assets from scene on-arrival JS.
 */

const path = require('path')
const { loadGameRuntimes, loadSceneOnArrival } = require('./extract-scene-js.js')

const args = process.argv.slice(2)
const help = args.includes('--help') || args.includes('-h')
const jsonOut = args.includes('--json')
const verbose = args.includes('--verbose')

const monthsIdx = args.indexOf('--months')
const months = monthsIdx >= 0 ? Math.max(1, parseInt(args[monthsIdx + 1], 10) || 3) : 3

if (help) {
    console.log(`Usage: node scripts/simulate-prosperity-months.js [options]

  --months N   Months to tick (default 3)
  --verbose    Print each block prosperity every month
  --json       JSON array of monthly snapshots
`)
    process.exit(0)
}

const SCENES = path.join(__dirname, '..', 'source', 'scenes')

function initQ() {
    const Q = loadGameRuntimes({
        refreshProjections: true,
        commitSeats: true,
    })
    Q.month = Q.month ?? 1
    Q.year = Q.year ?? 2300
    Q.phase = Q.phase ?? 1
    Q.crime_level = Q.crime_level ?? 1.1
    Q.trade_level = Q.trade_level ?? 1.12

    loadSceneOnArrival(
        path.join(SCENES, 'cards/organizing/organize_phase_tick.scene.dry'),
        { Q },
    )
    loadSceneOnArrival(
        path.join(SCENES, 'economic_assets_runtime.scene.dry'),
        { Q },
    )
    if (typeof Q.initEconomicAssets === 'function') {
        Q.initEconomicAssets()
    }
    if (typeof Q.monthly_tick_phase1 !== 'function') {
        throw new Error('simulate-prosperity-months: Q.monthly_tick_phase1 missing')
    }
    return Q
}

function snapshot(Q) {
    const state = Q.electionV2
    const blocks = (state && state.blocks) ? state.blocks : []
    const byBlock = []
    for (let i = 0; i < blocks.length; i++) {
        const b = blocks[i]
        if (b.population <= 0) { continue }
        byBlock.push({
            id: b.id,
            district: b.district.id,
            stratum: b.demographic.id,
            pop: b.population,
            prosperity: Math.round((b.prosperity ?? 1) * 10000) / 10000,
        })
    }
    return {
        month: Q.month,
        year: Q.year,
        trade_level: Q.trade_level,
        crime_level: Q.crime_level,
        ig: {
            Soylent: Q.prosperity_soylent,
            Magrail: Q.prosperity_magrail,
            Brazos: Q.prosperity_brazos,
            Families: Q.prosperity_families,
            Edges: Q.prosperity_edges,
            Sharks: Q.prosperity_sharks,
        },
        strata: {
            rich: Q.prosperity_rich,
            first: Q.prosperity_first,
            second: Q.prosperity_second,
            coop: Q.prosperity_coop,
            drone: Q.prosperity_drone,
            alien: Q.prosperity_alien,
            deeper: Q.prosperity_deeper,
            third_wave: Q.prosperity_third_wave,
        },
        blocks: byBlock,
        economic_sites: (Q.economicAssets || []).length,
    }
}

function printSnapshot(snap, label) {
    console.log(`\n=== ${label} (month ${snap.month}, trade ${snap.trade_level?.toFixed?.(4)}) ===`)
    console.log(
        'IG prosperity:',
        Object.entries(snap.ig)
            .map(([k, v]) => `${k}=${Number(v).toFixed(3)}`)
            .join('  '),
    )
    console.log(
        'Stratum avg:',
        Object.entries(snap.strata)
            .filter(([, v]) => v != null)
            .map(([k, v]) => `${k}=${Number(v).toFixed(3)}`)
            .join('  '),
    )
    if (verbose) {
        for (let i = 0; i < snap.blocks.length; i++) {
            const b = snap.blocks[i]
            console.log(
                `  ${b.district}/${b.stratum} pop=${b.pop} prosperity=${b.prosperity}`,
            )
        }
    } else {
        const extremes = snap.blocks.slice().sort((a, b) => b.prosperity - a.prosperity)
        const hi = extremes.slice(0, 3)
        const lo = extremes.slice(-3).reverse()
        console.log('  highest:', hi.map((b) => `${b.district}/${b.stratum} ${b.prosperity}`).join(', '))
        console.log('  lowest: ', lo.map((b) => `${b.district}/${b.stratum} ${b.prosperity}`).join(', '))
    }
    console.log(`  registered economic sites: ${snap.economic_sites}`)
}

const Q = initQ()
const history = [snapshot(Q)]
printSnapshot(history[0], 'Start')

for (let m = 0; m < months; m++) {
    Q.monthly_tick_phase1()
    Q.month = (Q.month ?? 1) + 1
    if (Q.month > 12) {
        Q.month = 1
        Q.year = (Q.year ?? 2300) + 1
    }
    history.push(snapshot(Q))
    printSnapshot(history[history.length - 1], `After tick ${m + 1}`)
}

if (jsonOut) {
    console.log(JSON.stringify(history, null, 2))
}

