    coop: [2, 0, 20, -3, -3, 0, 6],
    drone: [3, 0, 0, 3, 2, 0, 2],
    alien: [2, 0, 0, -6, -3, 0, 9],
    deeper: [2, 36, -5, 2, -2, 0, 6],
    third_wave: [3, 1, 0, 0, 1, 0, 4],
}

