const DEFAULT_GLOBAL = {
    competitiveTurnout: 1,
    igTurnoutMult: 1,
    competitiveTurnoutBonus: 0,
    competitiveScores: zeroPartyVotes(),
    softmaxTemperature: 1,
}

/** Example scenarios for CLI tuning. */
const SCENARIOS = {
    baseline: () => ({}),
    democratic_awakening: () => ({
