    Magrail: { Railyard: 1.35, Docks: 1.3, Aurora: 1.1 },
    Brazos: { Limelight: 1.4, Vats: 1.15, Pitts: 1.1 },
    Families: { Pitts: 1.5, Aurora: 1.2, Docks: 1.15 },
