}

const EXEC_SEATS = 150
const GUILD_SEATS = 35
const DISTRICT_SEATS = 15
const VOTE_SCALE = 10000
const EXEC_ELECTION_MONTH = 12
const GUILD_KEYS = ['Gold', 'White', 'Blue']

/** District council election month (1–12). Order: Docks … Deeps. */
const DISTRICT_ELECTION_MONTH = {
    Docks: 6,
    Aurora: 4,
    Vats: 2,
    Railyard: 11,
    Pitts: 5,
    Limelight: 6,
    Deeps: 8,
}

/** Starting prosperity for every voter block in the district (6 = Mikasa average). */
const MIKASA_BLOCK_PROSPERITY_BASE = 6
const DISTRICT_STARTING_PROSPERITY = {
    Docks: 8,
    Aurora: 7,
    Pitts: 4,
}

/** Population in 10,000s per district × stratum (authoritative; mirror to election-world-data.js for Node CLI). */
const DISTRICT_POPULATIONS = {
    Docks: {
        rich: 17, first: 42, second: 30, coop: 3, drone: 11, alien: 1, deeper: 1,
