            + ' slack capacity, '
            + totals.assets
            + ' assets ('
            + totals.sites
            + ' listed sites).'
        )
        root.appendChild(foot)
        return true
    }

    function tryPaint() {
        if (paint()) { return }
        attempts += 1
        if (attempts < maxAttempts) {
            setTimeout(tryPaint, 0)
        }
    }
    tryPaint()
}

